import{z as i,x as A,o as n,c as d,q as l,j as B,D as t,d as E,s as r,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"信号","description":"","frontmatter":{"title":"信号","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/signals.md","filePath":"cs/signals.md","lastUpdated":1791063341000}'),p={name:"cs/signals.md"};function m(D,a,c,h,C,P){const s=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=l('<h1 id="信号" tabindex="-1">信号 <a class="header-anchor" href="#信号" aria-label="Permalink to &quot;信号&quot;">​</a></h1><div class="epigraph"><p>信号是通知进程某事件已发生的软件中断；进程可以忽略、捕获或取默认动作。</p><footer>—— 据 Stevens and Rago, Advanced Programming in the UNIX Environment；POSIX 对 signal 的整理</footer></div><p><a href="/cs/iommu">上一课</a>把期限任务与分时对照完毕。设备 IRQ 走内核下半部；用户线程还缺一种<strong>针对自己的异步通知</strong>：子进程退出、终端键、闹钟、非法内存。缺口不是再调度一次，而是内核向进程投递一种编号事件——信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若父进程只能 <code>wait</code> 轮询，子进程退出的消息会迟到。若用管道专门传「你被中断了」，每个事件都要先建立通道。Unix 把一小类事件做成信号：内核置位，在该进程回到用户态的边界递送。缺口是：执行流在指令边界被拽去处理程序，再回来——像中断，但对象是进程，不是 CPU 向量。</p><p>本课不把实时信号排队语义写全，也不把 <code>sigaction</code> 的全部标志背完。</p><p><span class="marginnote">默认动作可以是终止、核心转储、停止或忽略。<code>SIGKILL</code> 与 <code>SIGSTOP</code> 不能捕获，以免进程拒绝被内核回收。</span></p><p><span class="marginnote">术语翻译：信号本质是「内核往进程的账本上记一个编号」。进程醒来时翻账本：\\(\\mathrm{SIGCHLD}\\)（14 号左右，子进程走了）、\\(\\mathrm{SIGALRM}\\)（闹钟响了）……每个编号对应三种态度之一——忽略、跑处理函数、或取默认动作。</span></p><p><span class="marginnote">常见误区：初学者容易把信号想象成一条随时插队执行的代码通道。实际上处理函数借用的是<strong>当前正在跑的线程</strong>的执行流——它在任意指令边界把 PC 拽走，跑完再拽回来。这正是处理函数里不敢随便动全局数据的原因：它可能在主流程改到一半时介入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在 PCB 里记 pending 与 blocked 集合。递送点通常是从内核返回用户之前：若有未阻塞信号，改用户 PC 指向处理函数，并安排返回时回到原指令。处理函数在用户态跑，仍受页表与特权限制；它要再请内核，还走<a href="/cs/syscall-path">系统调用路径</a>。</p>',11)),(n(),B(o,null,{default:t(()=>[r(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E5%86%85%E6%A0%B8%E4%BA%8B%E4%BB%B6%E6%88%96%20kill%22%5D%20--%3E%20PEND%5B%22%E8%BF%9B%E7%A8%8B%20pending%22%5D%0A%20%20PEND%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E5%89%8D%E6%A3%80%E6%9F%A5%22%5D%0A%20%20RET%20--%3E%20HND%5B%22%E7%94%A8%E6%88%B7%E5%A4%84%E7%90%86%E5%87%BD%E6%95%B0%22%5D%0A%20%20HND%20--%3E%20OLD%5B%22%E5%9B%9E%E5%88%B0%E5%8E%9F%20PC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("进程间也可以 "),e("code",null,"kill"),E(" 投递，这是一种极窄的 IPC，几乎不携带数据。真正传字节是下一课管道。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("信号把「异步」从设备扩到软件：闹钟到期、管道对端关闭、窗口大小变化，都可以在线程不知情的指令间隙插入。与"),e("a",{href:"/cs/interrupt-bottom-half"},"中断下半部"),E("的分工：硬件 IRQ 先在内核消化；只有需要该用户进程知情时才置信号。调度仍然决定进程何时跑；信号不代替调度器。")],-1)),a[6]||(a[6]=e("p",null,"同一根「异步」的线上，硬件中断与信号各自走哪一段？分工的边界画在这里：",-1)),(n(),B(o,null,{default:t(()=>[r(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC1%5B%22%E8%AE%BE%E5%A4%87%E6%8B%89%20IRQ%20%E7%BA%BF%22%5D%20--%3E%20K1%5B%22CPU%20%E8%BF%9B%E5%86%85%E6%A0%B8%3Cbr%3E%E4%B8%8A%E5%8D%8A%E9%83%A8%E5%BF%AB%E9%80%9F%E5%93%8D%E5%BA%94%22%5D%0A%20%20K1%20--%3E%20K2%5B%22%E4%B8%8B%E5%8D%8A%E9%83%A8%E6%85%A2%E6%85%A2%E6%B6%88%E5%8C%96%22%5D%0A%20%20K2%20--%3E%20Q%7B%22%E8%AF%A5%E7%94%A8%E6%88%B7%E8%BF%9B%E7%A8%8B%E9%9C%80%E8%A6%81%E7%9F%A5%E9%81%93%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%E4%B8%8D%E9%9C%80%E8%A6%81%20--%3E%20END1%5B%22%E5%86%85%E6%A0%B8%E5%86%85%E9%83%A8%E8%A7%A3%E5%86%B3%E5%AE%8C%E6%AF%95%22%5D%0A%20%20Q%20--%20%E9%9C%80%E8%A6%81%20--%3E%20SET%5B%22PCB%20%E9%87%8C%E7%BD%AE%20pending%20%E4%BD%8D%22%5D%0A%20%20SRC2%5B%22%E8%BD%AF%E4%BB%B6%E4%BA%8B%E4%BB%B6%EF%BC%9A%E9%97%B9%E9%92%9F%2F%E5%AD%90%E8%BF%9B%E7%A8%8B%E9%80%80%E5%87%BA%22%5D%20--%3E%20SET%0A%20%20SET%20--%3E%20BND%5B%22%E8%BF%9B%E7%A8%8B%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%E8%BE%B9%E7%95%8C%22%5D%0A%20%20BND%20--%3E%20USR%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E5%A4%84%E7%90%86%E5%87%BD%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>可以把它想象成前台与后台的分工：内核是前台接待（必须秒回 IRQ），用户进程是楼上办公室（内核写张便条贴在门口），楼上的人只有自己出来（回用户态）才会看到便条。</p><p>可重入问题：处理函数里调用不可重入库，会与主控制流抢同一用户锁。本课只点名，互斥是后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Windows APC 或 Mach 消息当成同一课对象。不讲信号在多线程里精确递送到哪条线程的全部 POSIX 规则，只承认：信号是进程级事件，线程可以有掩码。也不把信号当通用 RPC。</p><p>后课默认：进程可以被编号事件打断。要传的是字节流而不是一位事件，下一课用管道与 IPC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号是指向进程的软件中断，在回用户态时递送。</li><li>几乎不带数据；默认动作由内核规定。</li><li>字节级通信是管道的缺口。</li><li>出处：Stevens and Rago, <em>APUE</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const f=i(p,[["render",m]]);export{S as __pageData,f as default};
